    [["sfIss", "iss"], ["sfCtry", "ctry"], ["sfType", "type"], ["sfSt", "st"], ["sfGreen", "green"]].forEach(([id, k]) => $(id).onchange = e => { SF[k] = e.target.value; render(); });
