    if (x && pre) { pre.textContent = missPrompt(x); const btn = pre.nextElementSibling; if (btn && btn.dataset) for (const a in btn.dataset) if (/copy|prompt/i.test(a)) btn.dataset[a] = missPrompt(x); }
